  7	import com.pousadamarealta.exception.ApiException;
  8	import com.pousadamarealta.service.*;
  9	import io.javalin.Javalin;
 10	import io.javalin.json.JavalinJackson;
 11	
 12	import java.util.HashMap;
 13	import java.util.Map;
 14	
 15	public class Main {
 16	    public static void main(String[] args) {
 17	        String dbUrl = System.getenv("DB_URL");
 18	        String dbUser = System.getenv("DB_USER");
 19	        String dbPassword = System.getenv("DB_PASSWORD");
 20	        String portStr = System.getenv("PORT");
 21	
 22	        if (dbUrl == null) {
 23	            throw new RuntimeException("DB_URL environment variable is required");
 24	        }
 25	        if (dbUser == null) {
 26	            throw new RuntimeException("DB_USER environment variable is required");
 27	        }
 28	        if (dbPassword == null) {
 29	            throw new RuntimeException("DB_PASSWORD environment variable is required");
 30	        }
 31	
 32	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 33	
 34	        Database database = new Database(dbUrl, dbUser, dbPassword);
 35	
 36	        RoomService roomService = new RoomService(database);
 37	        MessageService messageService = new MessageService(database);
 38	        ReservationService reservationService = new ReservationService(database, roomService, messageService);
 39	        ReportService reportService = new ReportService(database);
 40	
 41	        RoomController roomController = new RoomController(roomService);
 42	        MessageController messageController = new MessageController(messageService);
 43	        ReservationController reservationController = new ReservationController(reservationService);
 44	        ReportController reportController = new ReportController(reportService);
 45	
 46	        ObjectMapper objectMapper = new ObjectMapper();
 47	        objectMapper.registerModule(new JavaTimeModule());
 48	
 49	        Javalin app = Javalin.create(config -> {
 50	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 51	        }).start(port);
 52	
 53	        app.exception(ApiException.class, (e, ctx) -> {
 54	            Map<String, String> error = new HashMap<>();
 55	            error.put("error", e.getErrorCode());
 56	            error.put("message", e.getMessage());
 57	            ctx.status(e.getStatusCode());
 58	            ctx.json(error);
 59	        });
 60	
 61	        app.exception(Exception.class, (e, ctx) -> {
 62	            e.printStackTrace();
 63	            Map<String, String> error = new HashMap<>();
 64	            error.put("error", "INTERNAL_ERROR");
 65	            error.put("message", "An internal error occurred");
 66	            ctx.status(500);
 67	            ctx.json(error);
 68	        });
 69	
 70	        app.get("/rooms", roomController::getAllRooms);
 71	
 72	        app.post("/reservations", reservationController::createReservation);
 73	        app.get("/reservations/{id}", reservationController::getReservation);
 74	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 75	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 76	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 77	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 78	        app.get("/reservations/{id}/document", reservationController::getDocument);
 79	
 80	        app.get("/messages", messageController::getAllMessages);
 81	
 82	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 83	        app.get("/reports/revenue", reportController::getRevenueReport);
 84	
 85	        System.out.println("Pousada Maré Alta - Sistema de Reservas iniciado na porta " + port);
 86	    }
 87	}
