 90	import java.sql.Connection;
 91	import java.sql.DriverManager;
 92	import java.sql.SQLException;
 93	import java.sql.Statement;
 94	
 95	public class Database {
 96	    private final String url;
 97	    private final String user;
 98	    private final String password;
 99	
100	    public Database(String url, String user, String password) {
101	        this.url = url;
102	        this.user = user;
103	        this.password = password;
104	        initializeSchema();
105	    }
106	
107	    public Connection getConnection() throws SQLException {
108	        return DriverManager.getConnection(url, user, password);
109	    }
110	
111	    private void initializeSchema() {
112	        try (Connection conn = getConnection();
113	             Statement stmt = conn.createStatement()) {
114	
115	            stmt.execute("""
116	                CREATE TABLE IF NOT EXISTS rooms (
117	                    number VARCHAR(10) PRIMARY KEY,
118	                    type VARCHAR(20) NOT NULL
119	                )
120	            """);
121	
122	            stmt.execute("""
123	                CREATE TABLE IF NOT EXISTS reservations (
124	                    id BIGSERIAL PRIMARY KEY,
125	                    room_number VARCHAR(10) NOT NULL,
126	                    guest_name VARCHAR(255) NOT NULL,
127	                    guest_email VARCHAR(255) NOT NULL,
128	                    guest_cpf VARCHAR(20) NOT NULL,
129	                    check_in DATE NOT NULL,
130	                    check_out DATE NOT NULL,
131	                    guests INTEGER NOT NULL,
132	                    rate_plan VARCHAR(30) NOT NULL,
133	                    company_code VARCHAR(50),
134	                    nights INTEGER NOT NULL,
135	                    subtotal DECIMAL(10, 2) NOT NULL,
136	                    discount DECIMAL(10, 2) NOT NULL,
137	                    total DECIMAL(10, 2) NOT NULL,
138	                    status VARCHAR(20) NOT NULL,
139	                    amount_paid DECIMAL(10, 2) NOT NULL,
140	                    refund DECIMAL(10, 2),
141	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
142	                )
143	            """);
144	
145	            stmt.execute("""
146	                CREATE TABLE IF NOT EXISTS messages (
147	                    id BIGSERIAL PRIMARY KEY,
148	                    channel VARCHAR(20) NOT NULL,
149	                    recipient VARCHAR(255) NOT NULL,
150	                    subject VARCHAR(500),
151	                    body TEXT NOT NULL
152	                )
153	            """);
154	
155	            stmt.execute("""
156	                INSERT INTO rooms (number, type) VALUES
157	                    ('101', 'STANDARD'),
158	                    ('102', 'STANDARD'),
159	                    ('201', 'DELUXE'),
160	                    ('202', 'DELUXE'),
161	                    ('301', 'SUITE')
162	                ON CONFLICT (number) DO NOTHING
163	            """);
164	
165	        } catch (SQLException e) {
166	            throw new RuntimeException("Failed to initialize database", e);
167	        }
168	    }
169	}

