  1	package com.pousadamarealta.service;
  2	
  3	import com.pousadamarealta.config.Database;
  4	import com.pousadamarealta.domain.*;
  5	import com.pousadamarealta.exception.ApiException;
  6	import com.pousadamarealta.service.rateplan.*;
  7	
  8	import java.math.BigDecimal;
  9	import java.sql.*;
 10	import java.time.LocalDate;
 11	import java.time.format.DateTimeFormatter;
 12	import java.time.temporal.ChronoUnit;
 13	import java.util.Map;
 14	
 15	public class ReservationService {
 16	    private final Database database;
 17	    private final RoomService roomService;
 18	    private final MessageService messageService;
 19	    private final Map<RatePlan, RatePlanStrategy> ratePlanStrategies;
 20	
 21	    public ReservationService(Database database, RoomService roomService, MessageService messageService) {
 22	        this.database = database;
 23	        this.roomService = roomService;
 24	        this.messageService = messageService;
 25	        this.ratePlanStrategies = Map.of(
 26	            RatePlan.STANDARD, new StandardRatePlan(),
 27	            RatePlan.NON_REFUNDABLE, new NonRefundableRatePlan(),
 28	            RatePlan.CORPORATE, new CorporateRatePlan(),
 29	            RatePlan.WEEKEND_PACKAGE, new WeekendPackageRatePlan(),
 30	            RatePlan.LONG_STAY, new LongStayRatePlan()
 31	        );
 32	    }
 33	
 34	    public Reservation createReservation(Reservation reservation) {
 35	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
 36	
 37	        int nights = (int) ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
 38	        reservation.setNights(nights);
 39	
 40	        if (reservation.getGuests() < 1) {
 41	            throw new ApiException(400, "INVALID_REQUEST", "At least one guest is required");
 42	        }
 43	
 44	        if (reservation.getGuests() > room.getCapacity()) {
 45	            throw new ApiException(422, "CAPACITY_EXCEEDED",
 46	                "Room capacity exceeded. Max capacity: " + room.getCapacity());
 47	        }
 48	
 49	        RatePlanStrategy strategy = ratePlanStrategies.get(reservation.getRatePlan());
 50	        strategy.validate(reservation, room);
 51	        strategy.calculatePricing(reservation, room);
 52	
 53	        checkRoomAvailability(reservation.getRoomNumber(), reservation.getCheckIn(),
 54	            reservation.getCheckOut(), null);
 55	
 56	        String sql = """
 57	            INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf,
 58	                check_in, check_out, guests, rate_plan, company_code, nights, subtotal,
 59	                discount, total, status, amount_paid)
 60	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
 61	            RETURNING id
 62	        """;
 63	
 64	        try (Connection conn = database.getConnection();
 65	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 66	
 67	            stmt.setString(1, reservation.getRoomNumber());
 68	            stmt.setString(2, reservation.getGuestName());
 69	            stmt.setString(3, reservation.getGuestEmail());
 70	            stmt.setString(4, reservation.getGuestCpf());
 71	            stmt.setDate(5, Date.valueOf(reservation.getCheckIn()));
 72	            stmt.setDate(6, Date.valueOf(reservation.getCheckOut()));
 73	            stmt.setInt(7, reservation.getGuests());
 74	            stmt.setString(8, reservation.getRatePlan().name());
 75	            stmt.setString(9, reservation.getCompanyCode());
 76	            stmt.setInt(10, reservation.getNights());
 77	            stmt.setBigDecimal(11, reservation.getSubtotal());
 78	            stmt.setBigDecimal(12, reservation.getDiscount());
 79	            stmt.setBigDecimal(13, reservation.getTotal());
 80	            stmt.setString(14, ReservationStatus.PENDING.name());
 81	            stmt.setBigDecimal(15, BigDecimal.ZERO);
 82	
 83	            try (ResultSet rs = stmt.executeQuery()) {
 84	                if (rs.next()) {
 85	                    reservation.setId(rs.getLong("id"));
 86	                }
 87	            }
 88	
 89	        } catch (SQLException e) {
 90	            throw new RuntimeException("Failed to create reservation", e);
 91	        }
 92	
 93	        return reservation;
 94	    }
 95	
 96	    public Reservation getReservation(Long id) {
 97	        String sql = """
 98	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
 99	                   guests, rate_plan, company_code, nights, subtotal, discount, total,
100	                   status, amount_paid, refund
101	            FROM reservations WHERE id = ?
102	        """;
103	
104	        try (Connection conn = database.getConnection();
105	             PreparedStatement stmt = conn.prepareStatement(sql)) {
106	
107	            stmt.setLong(1, id);
108	
109	            try (ResultSet rs = stmt.executeQuery()) {
110	                if (rs.next()) {
111	                    return mapReservation(rs);
112	                }
113	            }
114	
115	        } catch (SQLException e) {
116	            throw new RuntimeException("Failed to get reservation", e);
117	        }
118	
119	        throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found: " + id);
120	    }
121	
122	    public Reservation confirmReservation(Long id) {
123	        Reservation reservation = getReservation(id);
124	
125	        if (reservation.getStatus() != ReservationStatus.PENDING) {
126	            throw new ApiException(409, "OPERATION_NOT_ALLOWED",
127	                "Only pending reservations can be confirmed");
128	        }
129	
130	        updateReservationStatus(id, ReservationStatus.CONFIRMED);
131	        reservation.setStatus(ReservationStatus.CONFIRMED);
132	        reservation.setAmountPaid(reservation.getTotal());
133	        updateAmountPaid(id, reservation.getTotal());
134	
135	        sendConfirmationEmail(reservation);
136	
137	        return reservation;
138	    }
139	
140	    public Reservation cancelReservation(Long id) {
141	        Reservation reservation = getReservation(id);
142	
143	        if (reservation.getStatus() == ReservationStatus.CHECKED_IN ||
144	            reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
145	            reservation.getStatus() == ReservationStatus.CANCELLED) {
146	            throw new ApiException(409, "OPERATION_NOT_ALLOWED",
147	                "Cannot cancel reservation in status: " + reservation.getStatus());
148	        }
149	
150	        RatePlanStrategy strategy = ratePlanStrategies.get(reservation.getRatePlan());
151	        BigDecimal refund = strategy.calculateRefund(reservation);
152	
153	        updateReservationStatus(id, ReservationStatus.CANCELLED);
154	        updateRefund(id, refund);
155	
156	        reservation.setStatus(ReservationStatus.CANCELLED);
157	        reservation.setRefund(refund);
158	
159	        return reservation;
160	    }
161	
162	    public Reservation checkIn(Long id) {
163	        Reservation reservation = getReservation(id);
164	
165	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
166	            throw new ApiException(409, "OPERATION_NOT_ALLOWED",
167	                "Only confirmed reservations can check in");
168	        }
169	
170	        updateReservationStatus(id, ReservationStatus.CHECKED_IN);
171	        reservation.setStatus(ReservationStatus.CHECKED_IN);
172	
173	        return reservation;
174	    }
175	
176	    public Document checkOut(Long id) {
177	        Reservation reservation = getReservation(id);
178	
179	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
180	            throw new ApiException(409, "OPERATION_NOT_ALLOWED",
181	                "Only checked-in reservations can check out");
182	        }
183	
184	        updateReservationStatus(id, ReservationStatus.CHECKED_OUT);
185	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
186	
187	        return generateDocument(reservation);
188	    }
189	
190	    public Document getDocument(Long id) {
191	        Reservation reservation = getReservation(id);
192	
193	        if (reservation.getStatus() == ReservationStatus.PENDING) {
194	            throw new ApiException(409, "OPERATION_NOT_ALLOWED",
195	                "Document is only available for paid reservations");
196	        }
197	
198	        return generateDocument(reservation);
199	    }
200	
201	    private Document generateDocument(Reservation reservation) {
202	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
203	
204	        Document document = new Document();
205	        document.setTitle("Comprovante de reserva");
206	        document.setReservationId(reservation.getId());
207	        document.setGuestName(reservation.getGuestName());
208	        document.setGuestCpf(reservation.getGuestCpf());
209	        document.setRoomNumber(reservation.getRoomNumber());
210	        document.setRoomType(room.getType());
211	        document.setCheckIn(reservation.getCheckIn());
212	        document.setCheckOut(reservation.getCheckOut());
213	        document.setNights(reservation.getNights());
214	        document.setSubtotal(reservation.getSubtotal());
215	        document.setDiscount(reservation.getDiscount());
216	        document.setTotal(reservation.getTotal());
217	
218	        return document;
219	    }
220	
221	    private void sendConfirmationEmail(Reservation reservation) {
222	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
223	
224	        String receipt = formatReceipt(reservation, room);
225	
226	        String body = String.format("""
227	            Olá, %s!
228	
229	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
230	
231	            %s
232	
233	            A entrada é a partir das 14h, e a saída, até as 12h.
234	            Até breve!""", reservation.getGuestName(), receipt);
235	
236	        Message message = new Message(
237	            "EMAIL",
238	            reservation.getGuestEmail(),
239	            "Reserva confirmada - Pousada Maré Alta",
240	            body
241	        );
242	
243	        messageService.sendMessage(message);
244	    }
245	
246	    private String formatReceipt(Reservation reservation, Room room) {
247	        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
248	
249	        StringBuilder receipt = new StringBuilder();
250	        receipt.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
251	        receipt.append(String.format("Hóspede: %s (CPF %s)\n",
252	            reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
253	        receipt.append(String.format("Quarto: %s (%s)\n",
254	            reservation.getRoomNumber(), room.getType().name()));
255	        receipt.append(String.format("Entrada: %s | Saída: %s | %s\n",
256	            reservation.getCheckIn().format(formatter),
257	            reservation.getCheckOut().format(formatter),
258	            reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias"));
259	        receipt.append(String.format("Diárias: %s\n", formatMoney(reservation.getSubtotal())));
260	
261	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
262	            receipt.append(String.format("Desconto: %s\n", formatMoney(reservation.getDiscount())));
263	        }
264	
265	        receipt.append(String.format("Total: %s", formatMoney(reservation.getTotal())));
266	
267	        return receipt.toString();
268	    }
269	
270	    private String formatCpf(String cpf) {
271	        cpf = cpf.replaceAll("[^0-9]", "");
272	        if (cpf.length() == 11) {
273	            return String.format("%s.%s.%s-%s",
274	                cpf.substring(0, 3),
275	                cpf.substring(3, 6),
276	                cpf.substring(6, 9),
277	                cpf.substring(9, 11));
278	        }
279	        return cpf;
280	    }
281	
282	    private String formatMoney(BigDecimal amount) {
283	        return String.format("R$ %,.2f", amount).replace(",", "X").replace(".", ",").replace("X", ".");
284	    }
285	
286	    private void checkRoomAvailability(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeReservationId) {
