133	package com.pousadamarealta.service.rateplan;
134	
135	import com.pousadamarealta.domain.Reservation;
136	import com.pousadamarealta.domain.Room;
137	
138	import java.math.BigDecimal;
139	import java.math.RoundingMode;
140	import java.time.LocalDate;
141	
142	public class StandardRatePlan implements RatePlanStrategy {
143	
144	    @Override
145	    public void validate(Reservation reservation, Room room) {
146	    }
147	
148	    @Override
149	    public void calculatePricing(Reservation reservation, Room room) {
150	        BigDecimal subtotal = BigDecimal.ZERO;
151	        LocalDate date = reservation.getCheckIn();
152	
153	        while (date.isBefore(reservation.getCheckOut())) {
154	            BigDecimal nightRate = room.getNightlyRate();
155	            if (isHighSeason(date)) {
156	                nightRate = nightRate.multiply(new BigDecimal("1.20"))
157	                    .setScale(2, RoundingMode.HALF_EVEN);
158	            }
159	            subtotal = subtotal.add(nightRate);
160	            date = date.plusDays(1);
161	        }
162	
163	        subtotal = subtotal.setScale(2, RoundingMode.HALF_EVEN);
164	
