  2	
  3	import com.pousadamarealta.config.Database;
  4	
  5	import java.math.BigDecimal;
  6	import java.sql.Connection;
  7	import java.sql.Date;
  8	import java.sql.PreparedStatement;
  9	import java.sql.ResultSet;
 10	import java.sql.SQLException;
 11	import java.time.LocalDate;
 12	import java.time.YearMonth;
 13	import java.time.format.DateTimeFormatter;
 14	
 15	public class ReportService {
 16	    private final Database database;
 17	
 18	    public ReportService(Database database) {
 19	        this.database = database;
 20	    }
 21	
 22	    public String getOccupancyReport(LocalDate date) {
 23	        StringBuilder csv = new StringBuilder();
 24	        csv.append("room,type,reservation,check_in,check_out\n");
 25	
 26	        String sql = """
 27	            SELECT r.room_number, rm.type, r.id, r.check_in, r.check_out
 28	            FROM reservations r
 29	            JOIN rooms rm ON r.room_number = rm.number
 30	            WHERE r.status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
 31	            AND r.check_in <= ?
 32	            AND r.check_out > ?
 33	            ORDER BY r.room_number
 34	        """;
 35	
 36	        int occupiedRooms = 0;
 37	
 38	        try (Connection conn = database.getConnection();
 39	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 40	
 41	            stmt.setDate(1, Date.valueOf(date));
 42	            stmt.setDate(2, Date.valueOf(date));
 43	
 44	            try (ResultSet rs = stmt.executeQuery()) {
 45	                while (rs.next()) {
 46	                    csv.append(rs.getString("room_number")).append(",");
 47	                    csv.append(rs.getString("type")).append(",");
 48	                    csv.append(rs.getLong("id")).append(",");
 49	                    csv.append(rs.getDate("check_in").toLocalDate().format(DateTimeFormatter.ISO_LOCAL_DATE)).append(",");
 50	                    csv.append(rs.getDate("check_out").toLocalDate().format(DateTimeFormatter.ISO_LOCAL_DATE)).append("\n");
 51	                    occupiedRooms++;
 52	                }
 53	            }
 54	
 55	        } catch (SQLException e) {
 56	            throw new RuntimeException("Failed to generate occupancy report", e);
 57	        }
 58	
 59	        csv.append("total,").append(occupiedRooms).append("/5");
 60	
 61	        return csv.toString();
 62	    }
 63	
 64	    public String getRevenueReport(YearMonth month) {
 65	        StringBuilder csv = new StringBuilder();
 66	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 67	
 68	        LocalDate startDate = month.atDay(1);
 69	        LocalDate endDate = month.atEndOfMonth();
 70	
 71	        String sql = """
 72	            SELECT id, room_number, check_in, check_out, status, amount_paid, refund
 73	            FROM reservations
 74	            WHERE check_in >= ? AND check_in <= ?
 75	            AND (amount_paid > 0 OR refund > 0)
 76	            ORDER BY check_in, id
 77	        """;
 78	
 79	        BigDecimal totalRevenue = BigDecimal.ZERO;
 80	
 81	        try (Connection conn = database.getConnection();
 82	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 83	
 84	            stmt.setDate(1, Date.valueOf(startDate));
 85	            stmt.setDate(2, Date.valueOf(endDate));
 86	
 87	            try (ResultSet rs = stmt.executeQuery()) {
 88	                while (rs.next()) {
 89	                    BigDecimal amountPaid = rs.getBigDecimal("amount_paid");
 90	                    BigDecimal refund = rs.getBigDecimal("refund");
 91	                    if (refund == null) {
 92	                        refund = BigDecimal.ZERO;
 93	                    }
 94	
 95	                    BigDecimal netAmount = amountPaid.subtract(refund);
 96	
 97	                    csv.append(rs.getLong("id")).append(",");
 98	                    csv.append(rs.getString("room_number")).append(",");
 99	                    csv.append(rs.getDate("check_in").toLocalDate().format(DateTimeFormatter.ISO_LOCAL_DATE)).append(",");
100	                    csv.append(rs.getDate("check_out").toLocalDate().format(DateTimeFormatter.ISO_LOCAL_DATE)).append(",");
101	                    csv.append(rs.getString("status")).append(",");
102	                    csv.append(formatCsvAmount(netAmount)).append("\n");
103	
104	                    totalRevenue = totalRevenue.add(netAmount);
105	                }
106	            }
107	
108	        } catch (SQLException e) {
109	            throw new RuntimeException("Failed to generate revenue report", e);
110	        }
111	
112	        csv.append("total,").append(formatCsvAmount(totalRevenue));
113	
114	        return csv.toString();
115	    }
116	
117	    private String formatCsvAmount(BigDecimal amount) {
118	        return amount.toString();
119	    }
120	}
